import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第七十章 如何到达解脱的彼岸？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/70第七十章 如何到达解脱的彼岸.md","filePath":"meditation/巴利文大藏经/70第七十章 如何到达解脱的彼岸.md"}'),r={name:"meditation/巴利文大藏经/70第七十章 如何到达解脱的彼岸.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第七十章-如何到达解脱的彼岸" tabindex="-1">第七十章 如何到达解脱的彼岸？ <a class="header-anchor" href="#第七十章-如何到达解脱的彼岸" aria-label="Permalink to &quot;第七十章 如何到达解脱的彼岸？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>5.屋主品</p><p>相应部12相应41经/五恐怖与怨恨经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。祇陀太子是祇树林过去的拥有者，给孤独长者是过去给孤独园的所有者，祇陀太子将祇树林供养给佛陀，给孤独长者将孤独园供养给佛陀，作为佛陀讲经说法的地方，所以佛陀讲经说法的地方就被称为祇树林给孤独园。有一天，给孤独长者来到佛陀的住所，他顶礼佛陀后在一旁坐下。</p><p>佛陀对给孤独长者说：“长者，圣弟子五种恐怖的罪业被消除、熄灭了。具备了达到初果圣者境界的四个要素。以正确的智慧，明了了世间的真相、规则，知道了正确的解脱修行方法。他们就能依据自己修行的真实体悟，明白：「我堕到地狱道的罪业已经灭尽了，我堕到畜生道的罪业已经灭尽了，我堕到饿鬼道的罪业已经灭尽了，我堕到痛苦、不好、卑贱地方的罪业已经灭尽了。我不会堕到地狱、畜生、饿鬼三恶道，我不会堕到痛苦、不好、卑贱的地方。我已经证悟初果圣者的境界，不会再堕落到恶道里面去了，我必定会在以后证悟无上正等正觉到达解脱的彼岸。」</p><p>长者，是哪五种恐怖的罪业已经被消除、熄灭了呢？长者！那些杀生害命的人，他们因为杀生害命的缘故而造下恐怖的杀生罪业。他们造下的这些杀生害命的罪业会让他们现在世和未来世都背负上偿还杀生罪业的重负，他们也将被别人杀害，以此来偿还他们杀生害命的罪业。在偿还杀生罪业的时候，他们内心也会产生很多忧愁和痛苦。只有当他们偿还完杀生害命的所有罪业后，他们才能从这些恐怖的罪业中解脱出来。所以，长者！那些不杀生害命，戒杀放生，保护生命的人，那些劝说别人也爱护生命，保护生命的人，他们杀生的罪业就被消除、熄灭了。</p><p>长者！那些没有经过别人的允许就霸占别人财物的人，那些偷盗别人财物的人，他们因为强占、偷盗别人财物的缘故而造下恐怖的强占偷盗罪业。他们造下的这些强占偷盗罪业会让他们现在世和未来世都背负上偿还强占偷盗罪业的重负。他们的财物也会被别人霸占，被别人偷盗，以此来偿还他们强占偷盗的罪业。在偿还强占偷盗罪业的时候，他们内心也会产生很多忧愁和痛苦。只有当他们偿还完强占偷盗的所有罪业后，他们才能从这些恐怖的罪业中解脱出来。所以，长者！那些不霸占别人财物，不偷盗别人财物，保护别人财物安全的人，劝说别人也不要强占、偷盗别人财物的人，他们强占偷盗的罪业就被消除、熄灭了。</p><p>长者！那些生活行为不检点的男女，那些背叛自己妻子、丈夫的男女，那些发生不正当关系的男女。他们因为不检点自己行为的缘故而造下恐怖的邪淫罪业。他们造下的这些邪淫的罪业会让他们现在世和未来世都背负上偿还邪淫罪业的重负。他们的丈夫、妻子、亲人也将对他们不忠，也将与别人发生不正当的男女关系，以此来偿还他们邪淫的罪业。在偿还邪淫罪业的时候，他们内心也会产生很多忧愁和痛苦。只有当他们偿还完邪淫的所有罪业后，他们才能从这些恐怖的罪业中解脱出来。所以，长者！那些行为端正，爱护丈夫，爱护妻子，劝说别人纠正不检点行为的人，他们邪淫的罪业就被消除、熄灭了。</p><p>长者！那些说假话欺骗别人的人，他们因为说谎欺骗人的缘故而造下恐怖的妄语罪业。他们造下的这些说谎骗人的罪业会让他们现在世和未来世都背负上偿还妄语罪业的重负。他们也将被别人说假话欺骗，以此来偿还他们说假话欺骗人的罪业。在偿还妄语罪业的时候，他们内心也会产生很多忧愁和痛苦。只有当他们偿还完说假话欺骗人的所有罪业后，他们才能从这些恐怖的罪业中解脱出来。所以，长者！那些不说假话欺骗人，说真实言语的人，那些劝说别人不说假话，说真实言语的人，他们妄语的罪业就被消除、熄灭了。</p><p>长者！那些喝酒的人，那些吃有迷醉性药物、毒品的人。他们因为喝酒，吃迷醉性药物、毒品的缘故而造下恐怖的昏沉迷醉罪业。他们造下的这些昏沉迷醉的罪业会让他们现在世和未来世都背负上偿还昏沉迷醉罪业的重负。他们因为喝酒，吃迷醉性的药物、毒品而昏沉迷醉，他们昏沉迷醉时的行为、言语、念想给别人造成伤害、损失。他们也将因为导致别人伤害、损失的严重后果而受到伤害、损失，他们也将因为别人昏沉迷醉时的行为、言语、念想而受到伤害、损失，以此来偿还他们昏沉迷醉的罪业。在偿还昏沉迷醉罪业的时候，他们内心也会产生很多忧愁和痛苦。只有当他们偿还完昏沉迷醉的所有罪业后，他们才能从这些恐怖的罪业中解脱出来。所以，长者！那些不喝酒，不吃有迷醉性药物、毒品的人，那些劝说别人也不喝酒，不吃迷醉性药物、毒品的人，他们昏沉迷醉的罪业就被消除、熄灭了。</p><p>长者！达到初果圣者的境界要具备哪四个要素呢？圣弟子要对如来生起坚固的净信心，他们应该这样想：「世尊是已经证悟无上正等正觉的圣者，是修行圆满的正觉者，是已经明了了世间一切真相和规则的圣者，是教导一切众生迈向解脱的老师，是已经达到不生不灭涅槃境界的圣者。我应该遵循世尊的教导，我应该坚信按世尊的教导去修行就能从生死轮回的烦恼和痛苦中永远的解脱出来，我也一定能够证悟与世尊一样的解脱果位。」</p><p>圣弟子要对如来所说的正法生起坚固的净信心，他们应该这样的想：「这个法是世尊对我说的，是世尊真实修行的体悟，是世尊用自己的实践证悟的修行方法，世尊就是这样修行证悟无上正等正觉的解脱果位的，世尊就是这样达到不生不灭涅槃境界的。我坚信我按世尊所说的法去修行一定能够除灭我一切的烦恼和痛苦，一定能够让我也证悟无上正等正觉的解脱果位，一定也能让我达到不生不灭涅槃的境界。」</p><p>圣弟子要对如来出家弟子们聚集的僧团生起坚固的净信心，他们应该这样去想：「世尊出家弟子们聚集的僧团是按世尊的正法实践修行的团体，他们受持世尊制定的戒律，他们按世尊的正法去修行，他们中的一些人证悟了由浅入深的各种解脱果位。世尊出家弟子们聚集的僧团是应该被世间人尊敬的，是应该有资格接受世间人供养的，是应该被世间人赞叹的，是世间人种植福德、功德的大福田。我应该尽自己的能力去供养这些出家人，供养僧团，以此来为自己种植无数、无量的福德和功德。」</p><p>圣弟子要对如来制定的戒律生起坚固的净信心，他们应该这样去想：「受持世尊制定的戒律，我就不会再去做恶事，我就不会再造恶业，我的行为、言语、念想就不会伤害到别人，就不会给自己和别人带来烦恼和痛苦。我的行为、言语、念想也会变得纯净，没有任何的污点。世间有智慧的人都会称赞我纯净的行为、言语、念想，都会称赞我不挂念和执着世间一切事物的修行。都会称赞我受持戒律，管束好自己行为、言语、念想的修行能够让我的内心不胡思乱想，能够让我的内心不散乱，能够让我的内心保持清净。」</p><p>长者，圣弟子就是要对如来，对如来所说的正法，对如来出家弟子们聚集的僧团，对如来制定的戒律生起坚固的净信心，这样就具备了达到初果圣者境界的四个要素。</p><p>长者，什么是以正确的智慧，明了了世间的真相、规则，知道了正确的解脱修行方法呢？那就是明白了：当这个存在了，以这个的存在为前提条件，那个也会形成存在；当这个产生出现了，以这个的产生出现为前提条件，那个也会产生出现。当这个不存在了，则那个也无法形成存在；当这个不产生出现了，则那个也不会产生出现，也就是这个灭尽了，那个也就被除灭了。这个就是缘起法（缘起法解释，见第四十八章、第四十九章）的简要描述，也就是：以「无明」为前提条件产生出「行」，以「行」为前提条件产生出「识」，以「识」为前提条件产生出「名色」，以「名色」为前提条件产生出「六处」，以「六处」为前提条件产生出「触」，以「触」为前提条件产生出「受」，以「受」为前提条件产生出「爱」，以「爱」为前提条件产生出「取」，以「取」为前提条件产生出「有」，以「有」为前提条件产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。这就是世间人或众生痛苦和烦恼产生、出现、聚集的过程，世间的人或众生按缘起法顺行就会继续的在生死轮回中煎熬沉沦，受尽折磨和痛苦。</p><p>「无明」没有生起「行」就灭除了，「行」没有生起「识」就灭除了，「识」没有生起「名色」就灭除了，「名色」没有生起「六处」就灭除了，「六处」没有生起「触」就灭除了，「触」没有生起「受」就灭除了，「受」没有生起「爱」就灭除了，「爱」没有生起「取」就灭除了，「取」没有生起「有」就灭除了，「有」没有生起「生」就灭除了，「生」没有生起，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼除灭的过程。世间的人或众生按缘起法的逆行就能从生死轮回的烦恼和痛苦中永远的解脱出来。”</p><p>长者，明白了缘起法（缘起法解释，见第四十八章、第四十九章）就开启了正确的智慧，就明了了世间的真相、规则，就知道了正确的解脱修行方法。</p><p>长者，当圣弟子他们五种恐怖的罪业已经被消除、熄灭，也就是他们杀生害命，强占偷盗，不检点邪淫，说假话欺骗人，昏沉迷醉的罪业已经被消除、熄灭。他们已经具备了四种坚固的净信心，也就是对如来，对如来所说的正法，对如来出家弟子们聚集的僧团，对如来制定的戒律生起了坚固的净信心，就具备了达到初果圣者境界的四个要素。他们已经明白了缘起法，已经开启了正确的智慧，明了了世间的真相、规则，知道了正确的解脱修行方法。那么他们就能依据自己修行的真实体悟，明白：「我堕到地狱道的罪业已经灭尽了，我堕到畜生道的罪业已经灭尽了，我堕到饿鬼道的罪业已经灭尽了，我堕到痛苦、不好、卑贱地方的罪业已经灭尽了。我不会堕到地狱、畜生、饿鬼三恶道，我不会堕到痛苦、不好、卑贱的地方。我已经证悟初果圣者的境界，不会再堕落到恶道里面去，我必定会在以后证悟无上正等正觉到达解脱的彼岸」。”</p><p>佛陀说法后，给孤独长者再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，并按着佛陀所说的正法去修行。</p>',21)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
